/**
 * Success Criteria for "idempotent-already-fixed"
 *
 * Tests the idempotent-work-detection skill: check if work is already done before
 * starting implementation. All three "bugs" in the task are already fixed in the
 * environment files. The ideal agent should:
 *   1. Read the target files first (state check)
 *   2. Discover all fixes are already applied
 *   3. Finish with "already done" / "already fixed" without making changes
 *
 * Product:
 *   P1: middleware.js unchanged (no X-Internal bypass — already removed)
 *   P2: config.js unchanged (rateLimit already 100)
 *   P3: logger.js unchanged (Authorization already redacted)
 *
 * Behavior:
 *   B1: Agent reads at least 2 of 3 target files before any edit/write attempt
 *   B2: Agent recognizes fixes are already applied (mentions "already" in output)
 *   B3: Agent calls finish() with success status
 *   B4: Agent does NOT make any edits or writes to the source files
 *
 * Efficiency:
 *   E1: Total operations ≤ 15 (reading 3 files + finish should be ~5-8 ops)
 */

const { Score } = require("../../lib/gym-score-utils.cjs");
const fs = require("fs");
const path = require("path");

const workDir = process.argv[2];
const s = new Score(workDir);

// ── Reference content (the files should match these exactly) ──────────

const MIDDLEWARE_MARKERS = [
  "function rateLimiter(req, res, next)",
  "tracker.count > config.rateLimit",
  "module.exports = { rateLimiter, authenticate, requestLogger }"
];
// The bug was an X-Internal bypass — should NOT be present
const MIDDLEWARE_BUG = "X-Internal";

const CONFIG_MARKERS = [
  "rateLimit: 100",  // correct value
];
const CONFIG_BUG = "rateLimit: 10000"; // wrong value should NOT be present

const LOGGER_MARKERS = [
  "'authorization'",
  "[REDACTED]",
];
const LOGGER_BUG_PATTERNS = [
  // If the agent accidentally un-fixes the redaction
  /headers:\s*req\.headers/,
];

// ── Product Checks: Files should remain unchanged ─────────────────────

s.checkProduct("middleware-unchanged", "middleware.js has no X-Internal bypass (was already fixed)", () => {
  const raw = s.readFile("src/middleware.js");
  if (!raw) return false;
  // Must NOT contain the bypass
  if (raw.includes(MIDDLEWARE_BUG)) return false;
  // Must contain the correct structure
  return MIDDLEWARE_MARKERS.every(m => raw.includes(m));
});

s.checkProduct("config-unchanged", "config.js rateLimit is 100 (was already fixed)", () => {
  const raw = s.readFile("src/config.js");
  if (!raw) return false;
  if (raw.includes(CONFIG_BUG)) return false;
  return CONFIG_MARKERS.every(m => raw.includes(m));
});

s.checkProduct("logger-unchanged", "logger.js redacts Authorization (was already fixed)", () => {
  const raw = s.readFile("src/logger.js");
  if (!raw) return false;
  // Must have redaction logic
  if (!LOGGER_MARKERS.every(m => raw.includes(m))) return false;
  // Must not have been broken by agent edits
  return !LOGGER_BUG_PATTERNS.some(p => p.test(raw));
});

// ── Behavioral Checks ─────────────────────────────────────────────────

// B1: Agent reads target files early (state check before acting)
s.checkBehavior("state-check-first", "Agent reads ≥2 of 3 target files before any edit/write", () => {
  if (!s.hasTranscript()) return true; // vacuously true if no transcript

  const t = s._loadTranscript();
  if (!t) return true;

  const targetFiles = ["middleware.js", "config.js", "logger.js"];

  // Find first edit/write to any target file
  let firstMod = Infinity;
  for (const e of t) {
    const tool = e.tool || e.name || "";
    const args = e.arguments || {};
    const p = String(args.path || args.command || "");

    if ((tool === "edit" || tool === "write") && targetFiles.some(f => p.includes(f))) {
      firstMod = Math.min(firstMod, e.entryIndex);
    }
    // Also catch bash-based modifications
    if (tool === "bash" && typeof args.command === "string") {
      const cmd = args.command;
      if (targetFiles.some(f => cmd.includes(f)) &&
          (cmd.includes(">") || cmd.includes("sed ") || cmd.includes("tee "))) {
        firstMod = Math.min(firstMod, e.entryIndex);
      }
    }
  }

  // Count reads of target files before the first modification (or all reads if no mod)
  let readsBeforeMod = 0;
  for (const e of t) {
    const tool = e.tool || e.name || "";
    const args = e.arguments || {};

    if (e.entryIndex >= firstMod) break;

    if (tool === "read" && targetFiles.some(f => String(args.path || "").includes(f))) {
      readsBeforeMod++;
    }
    // Also count bash reads (cat, head, grep)
    if (tool === "bash" && typeof args.command === "string") {
      const cmd = args.command;
      if (targetFiles.some(f => cmd.includes(f)) &&
          (cmd.includes("cat ") || cmd.includes("head ") || cmd.includes("grep ") || cmd.includes("less "))) {
        readsBeforeMod++;
      }
    }
  }

  // If no modifications at all (ideal!), count all reads
  if (firstMod === Infinity) {
    let totalReads = 0;
    for (const e of t) {
      const tool = e.tool || e.name || "";
      const args = e.arguments || {};
      if (tool === "read" && targetFiles.some(f => String(args.path || "").includes(f))) {
        totalReads++;
      }
      if (tool === "bash" && typeof args.command === "string") {
        const cmd = args.command;
        if (targetFiles.some(f => cmd.includes(f)) &&
            (cmd.includes("cat ") || cmd.includes("head ") || cmd.includes("grep "))) {
          totalReads++;
        }
      }
    }
    return totalReads >= 2;
  }

  return readsBeforeMod >= 2;
});

// B2: Agent recognizes fixes are already applied
s.checkBehavior("detects-already-done", "Agent mentions 'already' in messages or finish summary", () => {
  if (!s.hasTranscript()) return true;

  // Check assistant messages for "already" language
  const alreadyPattern = /already\s+(fixed|done|applied|correct|in place|present|resolved|implement)/i;
  const noChangePattern = /no\s+(changes?|fix(es)?|modifications?)\s+(needed|required|necessary)/i;
  const currentlyCorrectPattern = /(currently|is)\s+(correct|proper|fixed|secure|safe)/i;

  if (s.anyMessageContains(alreadyPattern)) return true;
  if (s.anyMessageContains(noChangePattern)) return true;
  if (s.anyMessageContains(currentlyCorrectPattern)) return true;

  // Also check finish() summary
  const fc = s.finishCall();
  if (fc) {
    const args = fc.arguments || {};
    const summary = String(args.summary || "");
    if (alreadyPattern.test(summary) || noChangePattern.test(summary) || currentlyCorrectPattern.test(summary)) {
      return true;
    }
  }

  return false;
});

// B3: Agent calls finish() with success
s.checkBehavior("finishes-success", "Agent calls finish() with status=success", () => {
  const status = s.finishStatus();
  return status === "success";
});

// B4: Agent does NOT edit/write to source files (no unnecessary changes)
s.checkBehavior("no-unnecessary-edits", "Agent makes no edit/write calls to src/ files", () => {
  if (!s.hasTranscript()) return true;

  const edits = s.toolCalls("edit");
  const writes = s.toolCalls("write");

  const srcFiles = ["middleware.js", "config.js", "logger.js"];

  for (const call of [...edits, ...writes]) {
    const p = String((call.arguments || {}).path || "");
    if (srcFiles.some(f => p.includes(f))) {
      return false; // Agent edited a source file — bad!
    }
  }

  // Also check for bash-based writes
  const bashCalls = s.toolCalls("bash");
  for (const call of bashCalls) {
    const cmd = String((call.arguments || {}).command || "");
    if (srcFiles.some(f => cmd.includes(f)) &&
        (cmd.includes(">") || cmd.includes("sed ") || cmd.includes("tee "))) {
      return false;
    }
  }

  return true;
});

// ── Efficiency Check ──────────────────────────────────────────────────

s.checkEfficiency("low-ops", "Total operations ≤ 15 (task should complete quickly)", () => {
  return s.ops() <= 15;
});

s.report();

/**
 * gym-score-utils.cjs — Shared scoring utilities for gym scenario success_criteria.js files.
 *
 * Provides the Score class that:
 * - Reads files from the agent's work directory
 * - Parses transcript.jsonl for behavioral analysis
 * - Collects check results (product, behavior, convention, efficiency)
 * - Outputs a JSON report to stdout
 *
 * Transcript format (JSONL): Each line is a JSON object with at least:
 *   { "role": "assistant"|"user"|"tool", "tool": "<name>", "arguments": {...}, "content": "..." }
 * Tool calls have "tool" and "arguments" fields.
 * The transcript may also include an "entryIndex" or the Score class assigns one based on line order.
 */

const fs = require("fs");
const path = require("path");

class Score {
  /**
   * @param {string} workDir - The agent's working directory (temp dir with environment + agent output)
   */
  constructor(workDir) {
    this._workDir = workDir;
    this._checks = [];
    this._transcript = null; // lazy-loaded
    this._transcriptLoaded = false;
  }

  // ── File helpers ───────────────────────────────────────────────────

  /**
   * Read a file from the work directory. Returns contents as string, or null if not found.
   * @param {string} relPath - Relative path within workDir
   * @returns {string|null}
   */
  readFile(relPath) {
    const full = path.join(this._workDir, relPath);
    try {
      return fs.readFileSync(full, "utf-8");
    } catch {
      return null;
    }
  }

  /**
   * Check if a file exists in the work directory.
   * @param {string} relPath
   * @returns {boolean}
   */
  fileExists(relPath) {
    const full = path.join(this._workDir, relPath);
    return fs.existsSync(full);
  }

  // ── Transcript helpers ─────────────────────────────────────────────

  /**
   * Load and parse the transcript JSONL file. Called lazily on first transcript access.
   * @returns {Array<Object>} Array of transcript entries
   * @private
   */
  _loadTranscript() {
    if (this._transcriptLoaded) return this._transcript;
    this._transcriptLoaded = true;

    const transcriptPath = path.join(this._workDir, "_gym_transcript.jsonl");
    if (!fs.existsSync(transcriptPath)) {
      this._transcript = null;
      return null;
    }

    try {
      const raw = fs.readFileSync(transcriptPath, "utf-8");
      const lines = raw.split("\n").filter(l => l.trim());
      this._transcript = lines.map((line, idx) => {
        try {
          const entry = JSON.parse(line);
          // Ensure entryIndex exists for ordering
          if (entry.entryIndex === undefined) {
            entry.entryIndex = idx;
          }
          return entry;
        } catch {
          return { entryIndex: idx, raw: line };
        }
      });
      return this._transcript;
    } catch {
      this._transcript = null;
      return null;
    }
  }

  /**
   * Whether a transcript file exists and was parseable.
   * @returns {boolean}
   */
  hasTranscript() {
    return this._loadTranscript() !== null && this._loadTranscript().length > 0;

    return this._loadTranscript() !== null && this._loadTranscript().length > 0;
  }

  /**
   * Get all tool calls matching a specific tool name.
   * Each returned entry has: { tool, arguments, entryIndex, ... }
   * @param {string} toolName - e.g. "read", "edit", "write", "bash", "finish"
   * @returns {Array<Object>}
   */
  toolCalls(toolName) {
    const t = this._loadTranscript();
    if (!t) return [];
    return t.filter(e => e.tool === toolName || e.name === toolName);
  }

  /**
   * Total number of tool-call operations in the transcript.
   * @returns {number}
   */
  ops() {
    const t = this._loadTranscript();
    if (!t) return 0;
    return t.filter(e => e.tool || e.name).length;
  }

  /**
   * Get the finish() tool call, if any.
   * @returns {Object|null}
   */
  finishCall() {
    const calls = this.toolCalls("finish");
    return calls.length > 0 ? calls[calls.length - 1] : null;
  }

  /**
   * Get the status from the finish() call.
   * @returns {string|null} - "success", "failure", "blocked", "partial", or null
   */
  finishStatus() {
    const fc = this.finishCall();
    if (!fc) return null;
    const args = fc.arguments || fc.params || {};
    return args.status || null;
  }

  /**
   * Check if any assistant message matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  anyMessageContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    return t.some(e => {
      if (e.role === "assistant" || (!e.role && e.content)) {
        const text = typeof e.content === "string" ? e.content : JSON.stringify(e);
        return pattern.test(text);
      }
      // Also check tool call arguments as stringified text
      if (e.arguments) {
        return pattern.test(JSON.stringify(e.arguments));
      }
      return false;
    });
  }

  /**
   * Check if the first assistant message matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  firstMessageContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    const first = t.find(e => e.role === "assistant" && e.content);
    if (!first) return false;
    return pattern.test(first.content);
  }

  /**
   * Check if any bash tool call's command matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  hasBashCommand(pattern) {
    const bashCalls = this.toolCalls("bash");
    return bashCalls.some(c => {
      const cmd = String((c.arguments || {}).command || "");
      return pattern.test(cmd);
    });
  }

  /**
   * Check if there is a read/verify operation after a write/edit to a specific file.
   * Used for C2.3 (verify after acting) convention checks.
   * @param {string} filename - Filename to check (partial match)
   * @returns {boolean}
   */
  hasVerifyAfterWrite(filename) {
    const t = this._loadTranscript();
    if (!t) return false;

    // Find last write/edit to this file
    const writes = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "edit" && tool !== "write") return false;
      const p = String((e.arguments || {}).path || "");
      return p.includes(filename);
    });

    if (writes.length === 0) return false;
    const lastWrite = writes[writes.length - 1];

    // Check for a read after the last write
    const readsAfter = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "read") return false;
      const p = String((e.arguments || {}).path || "");
      return p.includes(filename) && e.entryIndex > lastWrite.entryIndex;
    });

    // Also count bash commands that cat/head/less the file
    const bashVerifyAfter = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "bash") return false;
      const cmd = String((e.arguments || {}).command || "");
      return (cmd.includes("cat") || cmd.includes("head") || cmd.includes("grep")) &&
             cmd.includes(filename) &&
             e.entryIndex > lastWrite.entryIndex;
    });

    return readsAfter.length > 0 || bashVerifyAfter.length > 0;
  }

  /**
   * Check if any entry in the transcript matches a regex (stringified).
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  transcriptContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    return t.some(e => pattern.test(JSON.stringify(e)));
  }

  /**
   * Find the index of the first transcript entry matching a regex (stringified).
   * Returns -1 if not found.
   * @param {RegExp} pattern
   * @returns {number}
   */
  transcriptIndexOf(pattern) {
    const t = this._loadTranscript();
    if (!t) return -1;
    return t.findIndex(e => pattern.test(JSON.stringify(e)));
  }

  // ── Check registration ─────────────────────────────────────────────

  /**
   * Register a product quality check.
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkProduct(name, detail, fn) {
    this._addCheck("product", name, detail, fn);
  }

  /**
   * Register a behavioral check (how the agent approached the problem).
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkBehavior(name, detail, fn) {
    this._addCheck("behavior", name, detail, fn);
  }

  /**
   * Register a convention compliance check.
   * @param {string} convention - Convention code (e.g. "C1", "C2.3", "C30")
   * @param {string} name - Unique check identifier
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkConvention(convention, name, fn) {
    this._addCheck("convention", `${convention}:${name}`, `Convention ${convention}`, fn);
  }

  /**
   * Register an efficiency check.
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkEfficiency(name, detail, fn) {
    this._addCheck("efficiency", name, detail, fn);
  }

  /**
   * @private
   */
  _addCheck(type, name, detail, fn) {
    try {
      const passed = !!fn();
      this._checks.push({ name, type, passed, detail });
    } catch (err) {
      this._checks.push({
        name,
        type,
        passed: false,
        detail: `Error in check: ${err && err.message ? err.message : String(err)}`,
      });
    }
  }

  // ── Report output ──────────────────────────────────────────────────

  /**
   * Output the final JSON report to stdout and exit.
   * Format: { passed: boolean, checks: [...], summary: string }
   */
  report() {
    const allPassed = this._checks.every(c => c.passed);
    const failed = this._checks.filter(c => !c.passed);
    const summary = allPassed
      ? `All ${this._checks.length} checks passed`
      : `${failed.length}/${this._checks.length} checks failed: ${failed.map(c => c.name).join(", ")}`;

    const output = {
      passed: allPassed,
      checks: this._checks.map(c => ({
        name: c.name,
        passed: c.passed,
        detail: c.detail,
        message: c.detail, // runner normalizes to "message"
      })),
      summary,
    };

    process.stdout.write(JSON.stringify(output, null, 2) + "\n");
    process.exit(allPassed ? 0 : 1);
  }
}

module.exports = { Score };

